/* Compteurs de jours : droits saisis, aucune acquisition légale supposée. */
(function(root){
function days(v){const s=String(v??0).replace(',','.');if(!/^\d+(\.\d{1,6})?$/.test(s)||Number(s)>100000)throw Error('Compteur de congés invalide : utilisez des jours positifs avec six décimales maximum.');const [a,b='']=s.split('.');return Number(a)*1000000+Number(b.padEnd(6,'0'));}
function calculate(v){if(v.leaveN1===''||v.leaveN1===undefined||v.leaveN===''||v.leaveN===undefined)return null;const n1=days(v.leaveN1),n=days(v.leaveN)+days(v.leaveAcquiredMonth||0),before1=days(v.leaveTakenN1||0),beforeN=days(v.leaveTakenN||0),taken=days(v.cpDays||0);if(before1>n1||beforeN>n)throw Error('Les congés déjà pris dépassent les droits : vérifiez les compteurs N−1 et N.');const from1=Math.min(taken,n1-before1),fromN=taken-from1;return{n1:n1/1000000,n:n/1000000,takenN1:(before1+from1)/1000000,takenN:(beforeN+fromN)/1000000,monthTaken:taken/1000000,taken:(before1+beforeN+taken)/1000000,balanceN1:(n1-before1-from1)/1000000,balanceN:(n-beforeN-fromN)/1000000,balance:(n1+n-before1-beforeN-taken)/1000000,excess:Math.max(0,fromN-(n-beforeN))/1000000};}
const api={calculate};root.LeaveBalances=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
